-- Price Increase Tracking (admin only): price updates sent to Skye Ingraham, built from the work mailbox.
-- Run once in the Supabase SQL editor (project clumhidxgzfkwzwrtngi). Safe to re-run: seed rows are only added when the table is empty.
create table if not exists price_updates (
  id             uuid primary key default gen_random_uuid(),
  part_no        text not null,
  prev_price     numeric,
  new_price      numeric,
  orig_new_price numeric,                -- first proposed price when it was later revised
  sent_by        text not null default '',
  sent_date      date,                   -- date the (first) price email went to Skye
  revised_date   date,                   -- date a revised proposal went to Skye
  effective_date date,
  reply          text not null default 'none' check (reply in ('none', 'confirmed', 'disputed', 'declined')),
  reply_date     date,
  implemented    boolean,                -- null = unknown
  source_subject text not null default '',
  source_date    date,
  notes          text not null default '',
  history        jsonb not null default '[]'::jsonb,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists price_updates_part_idx on price_updates (part_no);
alter table price_updates enable row level security;
grant all on price_updates to service_role;

insert into price_updates (part_no, prev_price, new_price, orig_new_price, sent_by, sent_date, revised_date, effective_date, reply, reply_date, implemented, source_subject, source_date, notes, history)
select * from (values
  ('114-018-066', 12.69::numeric, 14.93::numeric, null::numeric, 'Sakib Ahamed', '2026-09-23'::date, null::date, '2026-11-23'::date, 'none', null::date, null::boolean, 'Pricing Update Notification - PART# 114-018-066 & 828-006-728', '2026-09-23'::date, 'Effective date was first given as 10/31/2026 and corrected to 11/23/2026 on 9/24. Skye''s 10/22 table lists this part (+18%) but she only asked for review of 838-007-056 and 838-000-895; the 10/30 email says this price remains as previously proposed. No acceptance from Skye on file.', $j$[{"date":"2026-09-23","who":"Sakib Ahamed","text":"Sent pricing update 114-018-066 $12.69 to $14.93 and 828-006-728 $9.17 to $10.08, effective 10/31/2026. Rich Arnold added a note the same day that CAMCO is losing money on both parts."},{"date":"2026-09-24","who":"Sakib Ahamed","text":"Corrected the effective date from 10/31/2026 to 11/23/2026."},{"date":"2026-10-22","who":"Skye Ingraham","text":"After the Teams review, asked CAMCO to review only 838-007-056 and 838-000-895; listed 114-018-066 at +18% with no objection or approval."},{"date":"2026-10-30","who":"Sakib Ahamed","text":"Revised proposal email states 136-000-433, 114-018-066 and 828-006-728 remain as previously proposed."}]$j$::jsonb),
