  ('838-000-895', 3.41::numeric, 10.07::numeric, 12.37::numeric, 'Sakib Ahamed', '2026-09-16'::date, '2026-10-30'::date, '2026-11-16'::date, 'disputed', '2026-10-22'::date, null::boolean, 'Pricing Update Notification - PART# 838-007-056, 136-000-433 & 838-000-895', '2026-09-16'::date, 'Original proposal $12.37 (+263%) was challenged by Skye (benchmark about 50% lower). CAMCO revised it to $10.07 on 10/30. The revised email does not restate an effective date, so 11/16/2026 is assumed to still apply. Skye has not replied to the revision.', $j$[{"date":"2026-09-16","who":"Sakib Ahamed","text":"Sent $3.41 to $12.37, effective 9/30/2026."},{"date":"2026-10-06","who":"Sakib Ahamed","text":"Corrected the effective date to 11/16/2026."},{"date":"2026-10-22","who":"Skye Ingraham","text":"Said the revised unit cost is about 50% higher than the benchmark. Asked CAMCO to review."},{"date":"2026-10-30","who":"Sakib Ahamed","text":"Revised the proposal to $10.07 and stated the current $3.41 is well below cost."}]$j$::jsonb),
  ('114-019-767', 122.67::numeric, 142.7::numeric, null::numeric, 'Sakib Ahamed', '2026-10-30'::date, null::date, '2026-12-31'::date, 'none', null::date, null::boolean, 'Price Update Request – 114-019-767', '2026-10-30'::date, 'Material-only pass-through (steel, blast, freight): +$20.03. The email appears twice in Sent Items (9:49 PM and 9:52 PM; the second copies Rich Arnold and Leo McDonald). No reply from Skye yet.', $j$[{"date":"2026-10-30","who":"Sakib Ahamed","text":"Sent $122.67 to $142.70 (+16.3%), effective 12/31/2026, with an Oct-2024 vs today material cost table."}]$j$::jsonb),
